/**
 * The store console's chart of today's slots (PRD-031), drawn as plain SVG with no chart library: one bar per slot,
 * its height the places left, each with its time as a label a screen reader can say.
 * slotChartSvg([{ start: '18:00', end: '19:00', left: 2 }]) → '<svg …>…</svg>'.
 */
import { formatSlot } from './format-slot.js';

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);

export const slotChartSvg = (slots, { barWidth = 24, unit = 10 } = {}) => {
  const top = Math.max(1, ...slots.map((s) => s.left));
  const bars = slots.map((s, i) => {
    const h = s.left * unit;
    const label = `${formatSlot(s.start, s.end)}: ${s.left} places left`;
    return `<rect x="${i * (barWidth + 4)}" y="${top * unit - h}" width="${barWidth}" height="${h}"><title>${esc(label)}</title></rect>`;
  });
  return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Places left in today's slots" width="${slots.length * (barWidth + 4)}" height="${top * unit}">${bars.join('')}</svg>`;
};

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { slotChartSvg } from '../slot-chart.js';

test('slotChartSvg: one bar per slot, each with its time and places left', () => {
  const svg = slotChartSvg([{ start: '18:00', end: '19:00', left: 2 }, { start: '19:00', end: '20:00', left: 0 }]);
  assert.equal((svg.match(/<rect /g) ?? []).length, 2);
  assert.match(svg, /18:00–19:00: 2 places left/);
  assert.match(svg, /role="img"/);
});

